import pathlib,re
root=pathlib.Path(r"C:\Users\OSCRPION\Documents\claude\cafe-qr-system")
p=root/"static"/"menu.html"
s=p.read_text(encoding="utf-8")
s=re.sub(r"\.thumb \{ width:60px; height:60px; flex:none; border-radius:14px; background:var\(--subtle\); display:grid; place-items:center; font-size:30px; \}", ".thumb { width:60px; height:60px; flex:none; border-radius:14px; background:#fff; display:grid; place-items:center; font-size:30px; }", s)
s=s.replace(".thumb img { position:absolute; inset:0; width:100%; height:100%; object-fit:cover; display:block; }", ".thumb img { position:absolute; inset:0; width:100%; height:100%; object-fit:contain; background:#fff; display:block; }")
s=re.sub(r"// Local, license-cleared stock photos chosen to represent each item in the menu\.\nconst PRODUCT_PHOTOS = \{.*?\n\};\n", "// Each menu item has a separate locally stored product image.\n",s,flags=re.S)
old=next(line for line in s.splitlines() if line.startswith("const photoThumb ="))
new="const photoThumb = m => `<div class=\"thumb\"><span class=\"fallback\" aria-hidden=\"true\">${emoji(m)}</span><img src=\"../static/products/${m.id}.jpg\" alt=\"${esc(m.name)}\" loading=\"lazy\" decoding=\"async\" onerror=\"this.style.display='none'\"></div>`;"
s=s.replace(old,new)
if "PRODUCT_PHOTOS" in s or "../static/products/${m.id}.jpg" not in s: raise SystemExit("Image mapping replacement failed.")
p.write_text(s,encoding="utf-8")
